// Get dynamic client ID from previous node
const clientId = $input.first().json["Client ID"]?.trim();

if (!clientId) {
  throw new Error("Client ID not provided");
}

// Find the matching row from the Google Sheet
const matchedRow = items.find(item => item.json['Client ID']?.trim() === clientId);

if (!matchedRow) {
  throw new Error(`Client ID "${clientId}" not found in sheet`);
}

// Collect all competitors dynamically
const competitors = Object.keys(matchedRow.json)
  .filter(key => key.toLowerCase().startsWith('competitor'))
  .map(key => matchedRow.json[key])
  .filter(url => !!url);

// Return final data
return [
  {
    json: {
      "Client ID": clientId,
      "My Business": matchedRow.json['Website URL'] || '',
      "Industry": matchedRow.json['Client Industry'] || '',
      "Competitors": competitors
    }
  }
];
